package runelitehitchprofiler;

import java.util.*;
import java.util.concurrent.*;

/** Bounded in-memory breadcrumbs and low-frequency client-thread stack samples. */
final class HitchDiagnostics implements AutoCloseable
{
    private static final int MAX_STACK_SAMPLES = 40;
    private static final int MAX_STACKS = 6;
    private static final int MAX_CUES = 256;
    private static final long CUE_RETENTION_NANOS = TimeUnit.SECONDS.toNanos(5);
    private final Object stackLock = new Object();
    private final Map<String, Integer> stacks = new LinkedHashMap<>();
    private final Deque<Cue> cues = new ArrayDeque<>();
    private final ScheduledExecutorService sampler;
    private volatile Thread clientThread;
    private volatile long heartbeat;
    private volatile long severeThresholdNanos;
    private int samples;
    private boolean closed;

    HitchDiagnostics()
    {
        sampler = Executors.newSingleThreadScheduledExecutor(task -> {
            Thread thread = new Thread(task, "RuneLite Hitch Profiler stall sampler");
            thread.setDaemon(true);
            return thread;
        });
        sampler.scheduleAtFixedRate(this::sampleSafely, 20, 20, TimeUnit.MILLISECONDS);
    }

    /** Ends the previous frame interval, returns its samples, and arms sampling for the next one. */
    String onFrame(long now, int severeThresholdMs)
    {
        String previous;
        synchronized (stackLock)
        {
            previous = formatStacks();
            stacks.clear();
            samples = 0;
            clientThread = Thread.currentThread();
            severeThresholdNanos = TimeUnit.MILLISECONDS.toNanos(severeThresholdMs);
            heartbeat = now;
        }
        return previous;
    }

    void record(String kind, long nano)
    {
        synchronized (cues)
        {
            cues.addLast(new Cue(kind, nano));
            prune(nano - CUE_RETENTION_NANOS);
            while (cues.size() > MAX_CUES) cues.removeFirst();
        }
    }

    String describeGap(long start, long end, String stackSummary)
    {
        String events = summarizeCues(start, end);
        if (stackSummary == null || stackSummary.isEmpty())
            stackSummary = "No client-thread stack captured; possible JVM-wide pause or native/GPU wait.";
        return stackSummary + (events.isEmpty() ? "" : " | Nearby events: " + events);
    }

    void reset()
    {
        synchronized (stackLock)
        {
            heartbeat = 0;
            clientThread = null;
            stacks.clear();
            samples = 0;
        }
        synchronized (cues) { cues.clear(); }
    }

    private void sampleSafely()
    {
        try { sample(); }
        catch (RuntimeException ignored) { /* Diagnostics must never affect game capture. */ }
    }

    private void sample()
    {
        long beat = heartbeat;
        Thread target = clientThread;
        long threshold = severeThresholdNanos;
        if (closed || beat == 0 || target == null || System.nanoTime() - beat < threshold) return;
        synchronized (stackLock) { if (samples >= MAX_STACK_SAMPLES) return; }

        String signature = signature(target.getStackTrace());
        if (signature.isEmpty()) return;
        synchronized (stackLock)
        {
            if (heartbeat != beat || samples >= MAX_STACK_SAMPLES) return;
            samples++;
            if (stacks.containsKey(signature)) stacks.put(signature, stacks.get(signature) + 1);
            else if (stacks.size() < MAX_STACKS) stacks.put(signature, 1);
        }
    }

    private static String signature(StackTraceElement[] trace)
    {
        StringBuilder out = new StringBuilder();
        int included = 0;
        for (StackTraceElement frame : trace)
        {
            String name = frame.getClassName();
            if (name.startsWith("java.") || name.startsWith("javax.") || name.startsWith("jdk.")
                || name.startsWith("sun.") || name.startsWith("com.google.common.eventbus")
                || name.startsWith("net.runelite.client.eventbus")) continue;
            if (out.length() > 0) out.append(" <- ");
            out.append(name).append('.').append(frame.getMethodName());
            if (frame.getLineNumber() >= 0) out.append(':').append(frame.getLineNumber());
            if (++included == 4) break;
        }
        if (out.length() == 0 && trace.length > 0) out.append(trace[0].toString());
        return out.length() > 360 ? out.substring(0, 357) + "..." : out.toString();
    }

    private String formatStacks()
    {
        if (samples == 0) return "";
        List<Map.Entry<String, Integer>> ranked = new ArrayList<>(stacks.entrySet());
        ranked.sort((a,b) -> Integer.compare(b.getValue(), a.getValue()));
        StringBuilder out = new StringBuilder("Client-thread stack samples (20 ms sampling; ")
            .append(samples).append(" samples): ");
        for (int i=0;i<ranked.size();i++)
        {
            if (i>0) out.append(" | ");
            out.append(ranked.get(i).getValue()).append("x ").append(ranked.get(i).getKey());
            if (out.length() > 900) { out.setLength(897); out.append("..."); break; }
        }
        return out.toString();
    }

    private String summarizeCues(long start, long end)
    {
        Map<String, Integer> during = new LinkedHashMap<>(), before = new LinkedHashMap<>();
        synchronized (cues)
        {
            prune(start - CUE_RETENTION_NANOS);
            for (Cue cue : cues)
            {
                if (cue.nano >= start && cue.nano <= end) increment(during, cue.kind);
                else if (cue.nano >= start - CUE_RETENTION_NANOS && cue.nano < start) increment(before, cue.kind);
            }
        }
        String duringText = formatCounts(during), beforeText = formatCounts(before);
        if (!duringText.isEmpty() && !beforeText.isEmpty()) return "during [" + duringText + "]; preceding 5s [" + beforeText + "]";
        if (!duringText.isEmpty()) return "during [" + duringText + "]";
        if (!beforeText.isEmpty()) return "preceding 5s [" + beforeText + "]";
        return "";
    }

    private void prune(long cutoff)
    { while (!cues.isEmpty() && cues.peekFirst().nano < cutoff) cues.removeFirst(); }

    private static void increment(Map<String, Integer> counts, String kind)
    { counts.put(kind, counts.getOrDefault(kind, 0) + 1); }

    private static String formatCounts(Map<String, Integer> counts)
    {
        StringJoiner out = new StringJoiner(", ");
        counts.forEach((kind,count) -> out.add(kind + " " + count));
        String value = out.toString();
        return value.length() > 260 ? value.substring(0,257) + "..." : value;
    }

    @Override public void close()
    {
        closed = true;
        reset();
        sampler.shutdownNow();
    }

    private static final class Cue
    {
        final String kind;
        final long nano;
        Cue(String kind, long nano) { this.kind = kind; this.nano = nano; }
    }
}

package runelitehitchprofiler;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Conservative plain-language explanations for observed severe-hitch evidence. */
final class HitchExplanation
{
    private static final Pattern CLASS_FRAME = Pattern.compile(
        "(?<![\\w$])((?:[a-zA-Z_$][\\w$]*\\.)+[A-Z_$][\\w$]*)\\.[a-zA-Z_$][\\w$]*(?::\\d+)?");
    private static final Pattern CUE_COUNT = Pattern.compile("(?:object\\+|ground\\+)\\s+(\\d+)");

    private HitchExplanation() { }

    static Result explain(String evidence)
    {
        String detail = evidence == null ? "" : evidence;
        List<String> plugins = pluginNames(detail);
        String reason;
        String description;
        if (detail.matches("(?s).*?(GLMappedBuffer\\.map|GLBuffer\\.map|nglMapBuffer(?:Range)?).*"))
        {
            reason = "OpenGL buffer mapping was sampled";
            description = "A sampled client-thread stack entered an OpenGL buffer map call. This shows where a thread was sampled; it cannot tell whether CPU work, driver synchronization, or GPU progress accounts for the full frame gap.";
        }
        else if (detail.matches("(?s).*?(scanWidget|scanChildren|getDynamicChildren).*"))
        {
            reason = "A widget tree scan was sampled";
            description = "A sampled stack was walking interface or widget children. Repeated or deep scans can use client-thread time, but the sample does not measure their total cost or prove they caused the whole hitch.";
        }
        else if (detail.contains("No client-thread stack captured"))
        {
            reason = "No client-thread stack was captured";
            description = "The sampler did not observe a client-thread stack during this gap. The delay may have occurred between samples or outside that thread; this record cannot identify a cause.";
        }
        else if (detail.contains("map-start") || detail.contains("map-done")
            || detail.toLowerCase(java.util.Locale.ROOT).contains("premapload")
            || detail.toLowerCase(java.util.Locale.ROOT).contains("worldviewloaded"))
        {
            reason = "Map loading activity was nearby";
            description = "A map-load signal fell during the hitch or within the nearby-event window. Timing proximity is a clue, not proof that loading caused the gap.";
        }
        else if (sceneChanges(detail) >= 100)
        {
            reason = "Many scene objects changed nearby";
            description = "The nearby-event window contains " + sceneChanges(detail)
                + " object or ground-object changes. This can accompany a scene update; event counts are not render time and do not prove the changes caused the hitch.";
        }
        else if (!plugins.isEmpty())
        {
            reason = "Plugin code appeared in sampled stacks";
            description = "The sampler saw plugin code on the client thread during the frame gap. This identifies code that was active in sampled moments, not proof that it caused the full delay.";
        }
        else if (detail.contains("Client-thread stack samples"))
        {
            reason = "RuneLite client-thread work was sampled";
            description = "The recorded stack does not resolve to a readable plugin operation. The profiler can show the sampled frames, but cannot assign this gap to a specific cause.";
        }
        else
        {
            reason = "Cause not identified from this record";
            description = "The saved evidence is too limited to name a likely activity. Keep this event as an unresolved hitch rather than treating a guess as its cause.";
        }
        return new Result(reason, description, plugins, detail);
    }

    private static int sceneChanges(String detail)
    {
        int total = 0;
        Matcher matcher = CUE_COUNT.matcher(detail);
        while (matcher.find())
        {
            try { total += Integer.parseInt(matcher.group(1)); }
            catch (NumberFormatException ignored) { }
        }
        return total;
    }

    private static List<String> pluginNames(String detail)
    {
        Set<String> names = new LinkedHashSet<>();
        Matcher matcher = CLASS_FRAME.matcher(detail);
        while (matcher.find() && names.size() < 3)
        {
            String className = matcher.group(1);
            if (isPlatformClass(className)) continue;
            if (className.startsWith("rs117.hd.")) names.add("117 HD (" + className + ")");
            else names.add(className);
        }
        return new ArrayList<>(names);
    }

    private static boolean isPlatformClass(String name)
    {
        return name.startsWith("java.") || name.startsWith("javax.") || name.startsWith("jdk.")
            || name.startsWith("sun.") || name.startsWith("net.runelite.") || name.startsWith("org.lwjgl.")
            || name.startsWith("com.google.") || name.startsWith("com.sun.") || name.startsWith("org.slf4j.")
            || name.startsWith("ch.qos.") || name.startsWith("net.bytebuddy.");
    }

    static final class Result
    {
        final String reason, description, evidence;
        final List<String> plugins;

        Result(String reason, String description, List<String> plugins, String evidence)
        {
            this.reason = reason;
            this.description = description;
            this.plugins = plugins;
            this.evidence = evidence;
        }

        String asText()
        {
            StringBuilder text = new StringBuilder("Possible activity: ").append(reason).append('\n')
                .append(description);
            if (!plugins.isEmpty()) text.append("\nPlugin/class seen: ").append(String.join(", ", plugins));
            if (!evidence.isEmpty()) text.append("\n\nCaptured evidence:\n").append(evidence);
            return text.toString();
        }
    }
}

package runelitehitchprofiler;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.*;
import java.nio.ByteBuffer;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import net.runelite.client.util.Filepath;

/** Append-only JSON Lines event log with an occasionally refreshed HTML report. */
final class HitchLog
{
    static final String HEADER = "schema,session,timestamp,type,context,duration_ms,world_view,regions,near_load,detail";
    static final String FOOTER = "</tbody></table></body></html>\n";
    static final String HTML_HEADER = loadTemplate();
    private static final long REPORT_REFRESH_NANOS = TimeUnit.SECONDS.toNanos(30);
    private static final int MAX_LOG_BYTES = 100 * 1024 * 1024;
    private final ThreadPoolExecutor writer;
    private final Filepath directory, file, report;
    private volatile String error = "", savedHistory = "Reading saved events...";
    private final AtomicLong rejected = new AtomicLong();
    private long bytes, lastReportNanos;
    private volatile boolean ready;

    HitchLog(Filepath directory)
    {
        this.directory = directory;
        file = directory.joinSegment("sailing-hitches.jsonl");
        report = directory.joinSegment("sailing-hitches.html");
        writer = new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(2048), task -> {
            Thread thread = new Thread(task,"RuneLite Hitch Profiler log"); thread.setDaemon(true); return thread;
        });
        writer.execute(() -> {
            try
            {
                directory.createDirectories();
                if (!file.exists()) migrateLegacyHtml();
                bytes = file.exists() ? file.size() : 0;
                List<String> recent = new ArrayList<>();
                if (file.exists())
                {
                    try (BufferedReader in = file.openBufferedReader())
                    {
                        String line;
                        while ((line = in.readLine()) != null)
                        {
                            JsonObject event = parseEvent(line);
                            if (event == null) continue;
                            recent.add(historyLine(event));
                            if (recent.size() > 150) recent.remove(0);
                        }
                    }
                }
                savedHistory = recent.isEmpty() ? "No earlier events. New events appear here after restarting the plugin." : String.join("\n", recent);
                ready = true;
                refreshReport();
            }
            catch (IOException | RuntimeException e) { error = "Local session log unavailable. Check RuneLite's client log for details."; }
        });
    }

    void write(String row) { write(row, false); }

    void write(String row, boolean severe)
    {
        try
        {
            writer.execute(() -> {
                if (!ready || !error.isEmpty()) return;
                try
                {
                    JsonObject event = eventFromRow(row, severe);
                    byte[] data = (event.toString() + "\n").getBytes(StandardCharsets.UTF_8);
                    if (bytes + data.length > MAX_LOG_BYTES)
                    { error = "Local session log reached 100 MB. Archive it from your plugin data folder, then restart the plugin."; return; }
                    try (FileChannel channel = file.openFileChannel(StandardOpenOption.CREATE, StandardOpenOption.WRITE, StandardOpenOption.APPEND))
                    {
                        ByteBuffer buffer = ByteBuffer.wrap(data);
                        while (buffer.hasRemaining()) channel.write(buffer);
                    }
                    bytes += data.length;
                    if (System.nanoTime() - lastReportNanos >= REPORT_REFRESH_NANOS) refreshReport();
                }
                catch (IOException | RuntimeException e) { error = "Could not write the local session log. Check RuneLite's client log for details."; }
            });
        }
        catch (RejectedExecutionException e) { rejected.incrementAndGet(); }
    }

    String status()
    {
        String value = error.isEmpty()
            ? ready ? "Logging active · files stay local." : "Preparing local session files…"
            : error;
        return value + (rejected.get() == 0 ? "" : " | Dropped log rows: " + rejected.get());
    }
    String history() { return savedHistory; }

    void close()
    {
        try { writer.execute(() -> { if (ready && error.isEmpty()) refreshReport(); }); }
        catch (RejectedExecutionException ignored) { }
        writer.shutdown();
    }

    private void refreshReport()
    {
        try
        {
            StringBuilder html = new StringBuilder(HTML_HEADER);
            try (BufferedReader in = file.openBufferedReader())
            {
                String line;
                while ((line = in.readLine()) != null)
                {
                    JsonObject event = parseEvent(line);
                    if (event == null) continue;
                    String csv = row(event);
                    html.append(htmlRow(csv, event.get("severe").getAsBoolean()));
                }
            }
            html.append(FOOTER);
            Filepath temporary = directory.createTempFile("hitch-report-", ".tmp");
            try
            {
                temporary.write(html.toString());
                temporary.moveTo(report, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
            }
            finally { temporary.deleteIfExists(); }
            lastReportNanos = System.nanoTime();
        }
        catch (IOException | RuntimeException e) { error = "Could not refresh the HTML report. Check RuneLite's client log for details."; }
    }

    /** One-time import keeps existing HTML history when migrating to JSON Lines. */
    private void migrateLegacyHtml() throws IOException
    {
        if (!report.exists()) return;
        try (BufferedReader in = report.openBufferedReader(); FileChannel out = file.openFileChannel(StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE))
        {
            String line;
            while ((line = in.readLine()) != null)
            {
                if (line.startsWith("<!--record:"))
                {
                    boolean severe = line.contains("class=\"severe\"");
                    List<String> cells = readHtmlRow(line);
                    if (!cells.isEmpty())
                    {
                        JsonObject event = eventFromCells(cells, severe);
                        byte[] data = (event.toString() + "\n").getBytes(StandardCharsets.UTF_8);
                        ByteBuffer buffer = ByteBuffer.wrap(data);
                        while (buffer.hasRemaining()) out.write(buffer);
                    }
                }
            }
        }
        catch (IOException | RuntimeException e)
        {
            file.deleteIfExists();
            throw new IOException("Could not migrate the existing HTML log: " + e.getMessage(), e);
        }
    }

    private static JsonObject eventFromRow(String row, boolean severe)
    {
        List<String> cells = parse(row.trim());
        if (cells.size() != 10 && cells.size() != 11) throw new IllegalArgumentException("Expected ten or eleven log fields");
        return eventFromCells(cells, severe);
    }

    private static JsonObject eventFromCells(List<String> cells, boolean severe)
    {
        JsonObject event = new JsonObject();
        String[] names = {"schema","session","timestamp","type","context","duration_ms","world_view","regions","near_load","detail","location"};
        for (int i=0;i<names.length;i++) event.addProperty(names[i], i<cells.size()?cells.get(i):"");
        event.addProperty("severe", severe);
        return event;
    }

    private static JsonObject parseEvent(String line)
    {
        try
        {
            JsonObject event = new JsonParser().parse(line).getAsJsonObject();
            if (!event.has("schema") || !event.has("timestamp") || !event.has("type")) return null;
            if (!event.has("location")) event.addProperty("location", "");
            if (!event.has("severe")) event.addProperty("severe", false);
            return event;
        }
        catch (RuntimeException e) { return null; }
    }

    private static String historyLine(JsonObject event)
    {
        String duration = string(event,"duration_ms"), detail = string(event,"detail");
        return string(event,"timestamp") + " | " + string(event,"type") + " | " + string(event,"context")
            + (duration.isEmpty() ? "" : " | " + duration + " ms") + "\n" + detail + "\n";
    }

    private static String row(JsonObject event)
    {
        StringJoiner out = new StringJoiner(",");
        String[] names = {"schema","session","timestamp","type","context","duration_ms","world_view","regions","near_load","detail","location"};
        for (String name : names)
        {
            String value = string(event,name).replace('\r',' ').replace('\n',' ');
            out.add("\"" + value.replace("\"","\"\"") + "\"");
        }
        return out.toString() + "\n";
    }

    private static String string(JsonObject object, String key)
    { return object.has(key) && !object.get(key).isJsonNull() ? object.get(key).getAsString() : ""; }

    private static String loadTemplate()
    {
        try (InputStream in = HitchLog.class.getResourceAsStream("/runelitehitchprofiler/report-header.html"))
        {
            if (in == null) throw new IOException("Report template is missing");
            return new String(in.readAllBytes(), StandardCharsets.UTF_8);
        }
        catch (IOException ex) { throw new IllegalStateException("Cannot load report template", ex); }
    }

    /** Retained for legacy-report migration and compatibility with existing log-format checks. */
    static String upgradeReport(String original) throws IOException
    {
        if (!original.startsWith("<!doctype html>\n<!-- sailing-hitch-finder-html-v1 -->\n") || !original.endsWith(FOOTER))
            throw new IOException("Unrecognised or incomplete log; file left unchanged");
        int body = original.indexOf("<tbody>");
        if (body < 0) throw new IOException("Missing event table; file left unchanged");
        String rows = original.substring(body + "<tbody>".length());
        if (rows.startsWith("\n")) rows = rows.substring(1);
        return HTML_HEADER + rows;
    }

    static String htmlRow(String row, boolean severe)
    {
        List<String> cells = parse(row.trim());
        if (cells.size() != 10 && cells.size() != 11) throw new IllegalArgumentException("Expected ten or eleven log fields");
        StringBuilder html = new StringBuilder("<!--record:")
            .append(Base64.getEncoder().encodeToString(row.getBytes(StandardCharsets.UTF_8)))
            .append("--><tr>");
        for (int i=0;i<Math.min(10, cells.size());i++)
        {
            html.append(i==5 && severe && "HITCH".equals(cells.get(3)) ? "<td class=\"severe\">" : "<td>")
                .append(escapeHtml(cells.get(i))).append("</td>");
        }
        html.append("<td class=\"location-data\" hidden>")
            .append(cells.size() > 10 ? escapeHtml(cells.get(10)) : "").append("</td>");
        return html.append("</tr>\n").toString();
    }

    static List<String> readHtmlRow(String line)
    {
        if (!line.startsWith("<!--record:")) return Collections.emptyList();
        int end=line.indexOf("-->");
        if (end<0) return Collections.emptyList();
        try { return parse(new String(Base64.getDecoder().decode(line.substring(11,end)),StandardCharsets.UTF_8).trim()); }
        catch (IllegalArgumentException ex) { return Collections.emptyList(); }
    }

    private static String escapeHtml(String value)
    {
        return value.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
            .replace("\"","&quot;").replace("'","&#39;");
    }

    static String row(String session, long wall, String type, String context, String ms, String view, String regions, String near, String detail)
    { return row(session, wall, type, context, ms, view, regions, near, detail, ""); }

    static String row(String session, long wall, String type, String context, String ms, String view, String regions, String near, String detail, String location)
    {
        String[] cells = {"2",session,Instant.ofEpochMilli(wall).toString(),type,context,ms,view,regions,near,detail,location};
        StringJoiner out = new StringJoiner(",");
        for (String cell : cells) out.add("\"" + cell.replace('\r',' ').replace('\n',' ').replace("\"","\"\"") + "\"");
        return out + "\n";
    }

    static List<String> parse(String line)
    {
        List<String> values = new ArrayList<>(); StringBuilder cell = new StringBuilder(); boolean quote = false;
        for (int i=0;i<line.length();i++)
        {
            char c=line.charAt(i);
            if (c=='"')
            {
                if (quote && i+1<line.length() && line.charAt(i+1)=='"') { cell.append('"'); i++; }
                else quote=!quote;
            }
            else if(c==',' && !quote) { values.add(cell.toString()); cell.setLength(0); }
            else cell.append(c);
        }
        if (quote) return Collections.emptyList();
        values.add(cell.toString()); return values;
    }
}

package runelitehitchprofiler;

import java.util.*;

/** Client-thread owned measurements. No game API or disk access. */
final class HitchSession
{
    static final long WINDOW = 1_000_000_000L;
    final String id = UUID.randomUUID().toString();
    final int threshold, severeThreshold;
    final Deque<Entry> history = new ArrayDeque<>();
    final Deque<Entry> waiting = new ArrayDeque<>();
    final Deque<Long> loadSignals = new ArrayDeque<>();
    final Map<String, Stats> contexts = new LinkedHashMap<>();
    final Stats total = new Stats();
    long loads, correlated, dropped;

    HitchSession(int threshold, int severe)
    {
        this.threshold = threshold;
        this.severeThreshold = Math.max(threshold, severe);
        contexts.put("BOAT_LIKELY", new Stats());
        contexts.put("LAND_LIKELY", new Stats());
        contexts.put("UNKNOWN", new Stats());
    }

    Entry frame(long start, long end, long wall, String context)
    {
        return frame(start, end, wall, context, "");
    }

    Entry frame(long start, long end, long wall, String context, String location)
    {
        return frame(start, end, wall, context, location, "");
    }

    Entry frame(long start, long end, long wall, String context, String location, String diagnostic)
    {
        double ms = (end - start) / 1_000_000.0;
        total.add(ms, threshold, severeThreshold);
        contexts.get(context).add(ms, threshold, severeThreshold);
        if (ms < threshold) return null;
        Entry e = new Entry("HITCH", start, end, wall, ms, context, -1, -1, diagnostic, location);
        for (long signal : loadSignals)
            if (signal >= start - WINDOW && signal <= end + WINDOW) e.nearLoad = true;
        waiting.add(e);
        remember(e);
        return e;
    }

    void signal(long time)
    {
        loadSignals.add(time);
        while (loadSignals.size() > 256) loadSignals.removeFirst();
        for (Entry e : waiting)
            if (time >= e.start - WINDOW && time <= e.end + WINDOW) e.nearLoad = true;
    }

    Entry load(long start, long end, long wall, String context, int view, int regions)
    {
        loads++;
        signal(start);
        signal(end);
        Entry e = new Entry("LOAD_INTERVAL", start, end, wall, (end - start) / 1_000_000.0,
            context, view, regions, "PreMapLoad to WorldViewLoaded; partial interval only", "");
        remember(e);
        return e;
    }

    List<Entry> drain(long now, boolean force)
    {
        while (!loadSignals.isEmpty() && now - loadSignals.peek() > 60_000_000_000L) loadSignals.removeFirst();
        if (waiting.isEmpty() || (!force && now - waiting.peek().end <= WINDOW)) return Collections.emptyList();
        List<Entry> result = new ArrayList<>();
        while (!waiting.isEmpty() && (force || now - waiting.peek().end > WINDOW))
        {
            Entry e = waiting.removeFirst();
            e.finalized = true;
            if (e.nearLoad) correlated++;
            result.add(e);
        }
        while (!loadSignals.isEmpty() && now - loadSignals.peek() > 60_000_000_000L) loadSignals.removeFirst();
        return result;
    }

    Entry note(long time, String text)
    {
        Entry e = new Entry("NOTE", time, time, System.currentTimeMillis(), 0, "UNKNOWN", -1, -1, text, "");
        remember(e);
        return e;
    }

    private void remember(Entry e)
    {
        history.addFirst(e);
        while (history.size() > 300) history.removeLast();
    }

    String report()
    {
        StringBuilder b = new StringBuilder("RuneLite Hitch Profiler 2.0\nSession: ").append(id)
            .append("\nThresholds: ").append(threshold).append(" / ").append(severeThreshold).append(" ms\n")
            .append(total.describe()).append("\nCompleted map intervals: ").append(loads)
            .append("\nHitches near load signals: ").append(correlated)
            .append("\nPending correlation: ").append(waiting.size())
            .append("\nDropped capture events: ").append(dropped).append('\n');
        contexts.forEach((key, value) -> b.append(key).append(": ").append(value.describe()).append('\n'));
        return b.append("Frame gaps measure callback cadence, not GPU execution. Near-load means within 1 second of a load signal or a signal inside the gap; association does not prove cause.\nBoat context is inferred from camera focus; unknown is retained.\n").toString();
    }

    static final class Stats
    {
        long frames, hitches, severe;
        double millis, peak;
        final long[] histogram = new long[2001];
        void add(double ms, int threshold, int severeThreshold)
        {
            frames++; millis += ms; peak = Math.max(peak, ms);
            histogram[Math.min(2000, (int) Math.ceil(ms))]++;
            if (ms >= threshold) hitches++;
            if (ms >= severeThreshold) severe++;
        }
        int percentile(double q)
        {
            if (frames == 0) return 0;
            long target = (long) Math.ceil(frames * q), sum = 0;
            for (int i = 0; i < histogram.length; i++) { sum += histogram[i]; if (sum >= target) return i; }
            return 2000;
        }
        String describe()
        {
            return String.format(Locale.ROOT, "%.1f min sampled; %d hitches; %d severe; peak %.1f ms; median %s ms; p95 %s ms; %.1f hitches/min",
                millis / 60000, hitches, severe, peak, label(percentile(.5)), label(percentile(.95)), millis == 0 ? 0 : hitches * 60000 / millis);
        }
        private String label(int ms) { return ms == 2000 ? "2000+" : Integer.toString(ms); }
    }

    static final class Entry
    {
        final String type, context, detail, location;
        final long start, end, wall;
        final double ms;
        final int view, regions;
        boolean nearLoad, finalized;
        Entry(String type, long start, long end, long wall, double ms, String context, int view, int regions, String detail, String location)
        {
            this.type = type; this.start = start; this.end = end; this.wall = wall; this.ms = ms;
            this.context = context; this.view = view; this.regions = regions; this.detail = detail; this.location = location;
            finalized = !type.equals("HITCH");
        }
    }
}

